      "apstFocus": "<span style=\"font-weight: normal;\"><span data-start=\"186\" data-end=\"225\">2.1 Content and teaching strategies</span><br data-start=\"225\" data-end=\"228\">\n<span data-start=\"228\" data-end=\"260\">3.4 Select and use resources</span><br data-start=\"260\" data-end=\"263\">\n<span data-start=\"263\" data-end=\"298\">4.2 Manage classroom activities</span><br data-start=\"298\" data-end=\"301\">\n<span data-start=\"301\" data-end=\"332\">5.1 Assess student learning</span><br data-start=\"332\" data-end=\"335\">\n<span data-start=\"335\" data-end=\"359\">5.2 Provide feedback</span></span>",
      "curriculum": "<span style=\"font-weight: normal;\">The ways that governments manage economic performance to improve living standards (ACHEK052)</span>",
      "crossCurriculum": "<span style=\"font-weight: normal;\"><span data-start=\"623\" data-end=\"641\">Sustainability</span><br data-start=\"641\" data-end=\"644\">\nLinks to externalities, environmental impacts and government/business responses.</span>",
      "generalCapabilities": "<span style=\"font-weight: normal;\">Literacy<br data-start=\"760\" data-end=\"763\">\nCritical and Creative Thinking<br data-start=\"793\" data-end=\"796\">\nEthical Understanding<br data-start=\"817\" data-end=\"820\">\nPersonal and Social Capability<br data-start=\"850\" data-end=\"853\">\nICT Capability</span>",
